insert into site_data (locale, data) values ('ko', E'{"faqs": [{"id": "f1", "answer": "평일 : 오전 10시 30분 ~ 오후 8시 (접수 마감 오후 7시 30분)\\n토요일 : 오전 11시 ~ 오후 4시 (100% 예약제)\\n토요일은 100% 예약제로 운영되므로, 진료를 원하시는 경우 희망일 전날까지 예약해 주시기 바랍니다.\\n일요일 및 공휴일은 휴진입니다.", "category": "진료", "question": "진료 시간이 어떻게 되나요?", "sortOrder": 0}, {"id": "f2", "answer": "예약 없이 방문하셔도 진료가 가능합니다.\\n다만, 예약 환자분을 우선으로 진료하므로 대기 시간이 발생할 수 있으며, 진료 상황에 따라 당일 접수가 조기 마감될 수 있습니다.\\n보다 편리한 진료를 위해 예약 후 방문해 주시기를 권장드립니다.", "category": "예약", "question": "예약 없이 방문해도 진료가 가능한가요?", "sortOrder": 1}, {"id": "f3", "answer": "건물 지하 주차장을 이용하실 수 있으며, 진료 시 최대 2시간까지 주차를 지원해 드립니다.\\n다만, 건물 주차장이 만차인 경우에는 아래의 인근 대체 주차장을 이용해 주시기 바랍니다. 대체 주차장 이용 시 발생하는 주차요금은 지원되지 않습니다.\\n※ 대체 주차장 안내\\n- KBS 본관 앞 노상공영주차장\\n- KBS 본관 뒤 노상공영주차장", "category": "이용", "question": "주차 시설이 있나요?", "sortOrder": 2}, {"id": "f4", "answer": "네, 가능합니다.\\n교통사고 후 발생한 목·허리·어깨 통증, 두통, 저림, 근육 긴장 등 사고 후유증에 대해 자동차보험 적용 진료가 가능합니다.\\n내원 시 보험사명, 담당자 연락처, 사고 접수번호를 알려주시면 보험사를 통한 진료비 청구를 도와드립니다.\\n다만, 환자분의 사고 접수 상태 및 보험 처리 가능 여부에 따라 적용 범위가 달라질 수 있으므로, 자세한 내용은 진료 시 상담을 통해 안내드리겠습니다.", "category": "보험", "question": "자동차보험 진료가 가능한가요?", "sortOrder": 3}], "about": {"facilityImages": ["https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025106891-816o6q.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025115296-al2935.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787024974124-e0ob1i.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787024990001-2py25g.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787024998457-aep3y9.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025016656-q69vq6.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025029104-yb6yiq.webp"], "philosophyBody": "몸이 건강해질 때, 아름다움도 함께 피어납니다.\\n\\n고운빛한의원은 단순히 증상을 없애는 치료보다, 몸이 본래 가진 회복력을 되찾는 것을 가장 중요하게 생각합니다.\\n통증을 줄이는 것, 피부를 맑게 하는 것, 몸의 균형을 회복하는 것.\\n이 모든 변화는 서로 연결되어 있으며, 건강한 몸에서 자연스러운 아름다움이 시작된다고 믿습니다.\\n한 분 한 분의 생활습관과 체질, 현재의 몸 상태를 세심하게 살피고, 충분한 상담과 정확한 진단을 바탕으로 가장 적합한 치료를 제안합니다.\\n\\n불필요한 치료보다 꼭 필요한 치료를,\\n일시적인 변화보다 오래 유지되는 건강한 변화를 목표로 진료합니다.\\n고운빛한의원은 몸과 마음이 편안해지는 공간에서, 건강과 아름다움이 함께 피어나는 순간을 함께하겠습니다.", "philosophyTitle": "진료 철학"}, "menus": [{"id": "m1", "href": "/", "label": "홈", "isHidden": false, "sortOrder": 0, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779287749874-snvdoz.webp"}, {"id": "m4", "href": "/about", "label": "소개", "isHidden": false, "sortOrder": 1, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289822668-x74srd.webp"}, {"id": "m3", "href": "/treatments", "label": "진료 내용", "isHidden": false, "sortOrder": 2, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289741816-8ntzs0.webp"}, {"id": "m2", "href": "/events", "label": "이벤트", "isHidden": false, "sortOrder": 3, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289727340-4afelh.webp"}, {"id": "m5", "href": "/community/notice", "label": "공지사항", "isHidden": false, "sortOrder": 4, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289767125-ghnel8.webp"}], "popup": {"id": "p1", "body": "<img src=\\"https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1786431991229-ty7sw0.webp\\"><p></p>", "image": "", "items": [{"body": "<img src=\\"https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1786431991229-ty7sw0.webp\\"><p></p>", "image": "", "title": "GRAND OPEN\\n오픈기념 특별가", "eventId": 1, "linkUrl": "/events/1", "imageOverlay": false}], "title": "GRAND OPEN\\n오픈기념 특별가", "linkUrl": "/events/1", "isActive": true}, "stats": [{"label": "진료 경력", "value": 15, "suffix": "년"}, {"label": "누적 환자", "value": 30000, "suffix": "명+"}, {"label": "환자 만족도", "value": 98, "suffix": "%"}, {"label": "진료 분야", "value": 5, "suffix": "개"}], "events": [{"id": 8, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787026443974-lnomjk.webp", "title": "볼링크 / 볼뉴머 / 슈링크", "endDate": "", "subtitle": "오픈특가", "startDate": "2026-08-18", "description": ""}, {"id": 7, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787026384128-h7wqp7.webp", "title": "점/사마귀/비립종 제거", "endDate": "", "subtitle": "오픈특가", "startDate": "2026-08-18", "description": ""}, {"id": 6, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787026132102-7a1cq6.webp", "title": "남성 바디 제모", "endDate": "", "subtitle": "오픈특가", "startDate": "2026-08-18", "description": ""}, {"id": 5, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787026108389-pe9es0.webp", "title": "남성 얼굴 제모", "endDate": "", "subtitle": "", "startDate": "2026-08-18", "description": ""}, {"id": 4, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787026056568-yvyqyd.webp", "title": "여성 바디 제모", "endDate": "", "subtitle": "오픈 특가", "startDate": "2026-08-18", "description": ""}, {"id": 3, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025942011-ojjav6.webp", "title": "여성 얼굴 제모", "endDate": "", "subtitle": "오픈특가", "startDate": "2026-08-18", "description": ""}, {"id": 2, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025865396-1ak4h6.webp", "title": "제네시스 듀얼토닝", "endDate": "", "subtitle": "오픈특가 2000천샷 보장", "startDate": "2026-08-18", "description": ""}, {"id": 1, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1786432442685-wqyk9s.webp", "title": "GRAND OPEN", "endDate": "", "subtitle": "오픈기념 특별가", "startDate": "2026-08-11", "description": "<p></p>"}], "notices": [{"id": 3, "date": "2026.06.01", "type": "notice", "title": "진료 시간 변경 안내 - 토요일 진료 추가", "content": "<p>안녕하세요. 고운빛한의원입니다.</p><p>보다 편리한 진료를 위해 <strong>토요일 진료를 새롭게 운영</strong>하게 되었습니다.</p><p><strong>■ 변경된 진료시간</strong></p><ul><li><p><strong>평일</strong> : 오전 10시 30분 ~ 오후 8시 (마지막 접수 오후 7시 30분)</p></li><li><p><strong><u>토요일</u></strong><u> : 오전 11시 ~ 오후 4시 </u></p></li><li><p><strong>일요일 및 공휴일</strong> : 휴진</p></li><li><p></p></li></ul><p>앞으로도 더욱 편안하고 만족스러운 진료를 위해 최선을 다하겠습니다.</p><p>감사합니다.</p>", "endDate": "", "startDate": "2026-06-01"}], "director": {"bio": ["가천대학교 한의과대학 졸업", "경희대학교 대학원 안이비인후피부과 석사 수료", "청주 자생한방병원 일반수련의 수료", "광덕안정한의원 이수점 진료원장", "로아한의원 강남점 진료원장", "척추신경추나의학회 정회원", "대한스포츠한의학회 팀닥터 과정 수료", "한의안면성형학회 정회원", "한방비만학회 정회원"], "name": "허은주", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/ko-1779287679673-s4ysvn.jpg", "quote": "건강과 아름다움을 함께 생각합니다.\\n고운빛한의원이 추구하는 아름다움은 건강을 바탕으로 완성됩니다.\\n피부와 몸은 하나로 연결되어 있으며, 진정한 변화는 균형이 회복될 때 더욱 오래 지속됩니다.\\n미용 시술과 한방 치료를 조화롭게 접목하여, 일시적인 개선이 아닌 건강과 아름다움이 함께하는 자연스러운 변화를 만들어갑니다.\\n고운빛은 오늘의 변화뿐 아니라 시간이 지나도 변함없이 이어지는 아름다움을 지향합니다.", "title": "대표원장", "nameEn": "HEO EUNJU"}, "showStats": false, "clinicInfo": {"name": "고운빛한의원", "hours": {"closed": "일·공휴일 휴진", "weekday": "평일 10:30 – 20:00", "saturday": "토요일 11:00 – 16:00"}, "phone": "02-783-7525", "address": "서울시 영등포구 국회대로62길 15, 광복회관 지하1층 고운빛한의원", "socialLinks": {"blog": "#", "kakao": "#", "instagram": "#"}, "bannerImages": {"about": "", "events": "", "community": "", "treatments": ""}, "defaultImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783758914500-yaanod.webp", "reservationUrl": "https://booking.naver.com/booking/16/bizes/1700671"}, "heroSlides": [{"id": 1, "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1780623209148-ho326v.webp", "label": "Korean Medicine Clinic", "title": "", "subtitle": ""}, {"id": 2, "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1780623296262-mazqvz.webp", "label": "Tradition meets Modern", "title": "", "subtitle": ""}, {"id": 3, "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1780623343534-hxg2sf.webp", "label": "Care from the Root", "title": "", "subtitle": ""}], "treatments": [{"id": 4, "slug": "beauty", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783511098146-wvihnm.webp", "title": "미용시술\\n진료", "number": "01", "description": "한의 미용 시술로 자연스러운 안면 라인과 피부 관리"}, {"id": 1, "slug": "pain", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783510400343-b1zyp6.webp", "title": "통증진료", "number": "02", "description": "허리·목·관절 등 만성 통증을 근본부터 회복하는 한의 치료"}, {"id": 2, "slug": "insurance", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783510978207-2ba1gw.webp", "title": "보약처방", "number": "03", "description": "내몸에 맞춘 보약으로 기력 회복과 면역력 강화"}, {"id": 5, "slug": "tonic", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783510262621-klqgda.webp", "title": "자동차보험진료", "number": "04", "description": "교통사고 후 통증·후유증을 보험 적용으로 안심 치료"}], "schedulePopup": {"id": "sp1", "rows": [{"day": "평일", "note": "19:30 접수마감", "hours": "10:30 – 20:00"}, {"day": "토요일", "note": "15:30 접수마감", "hours": "11:00 – 16:00"}, {"day": "일·공휴일", "hours": "휴진"}, {"day": "광복절 대체휴무", "hours": "휴진"}], "month": "2026.08", "title": "8월 진료 일정", "notice": "점심시간 14:00 – 15:30", "isActive": true}, "noticeEndedHide": 7}'::jsonb) on conflict (locale) do update set data = excluded.data;
insert into site_data (locale, data) values ('en', E'{"faqs": [{"id": "f1", "answer": "We are open weekdays from 9 AM to 7 PM, and Saturdays from 9 AM to 2 PM. We are closed on Sundays and public holidays.", "category": "Treatment", "question": "What are your office hours?", "sortOrder": 0}, {"id": "f2", "answer": "Walk-in patients are welcome when time permits, but we prioritize patients with reservations. We recommend booking in advance through Naver Reservation.", "category": "Reservation", "question": "Can I visit without a reservation?", "sortOrder": 1}, {"id": "f3", "answer": "Free parking is available in the building basement. Patients receive 2 hours of complimentary parking.", "category": "Facility", "question": "Is parking available?", "sortOrder": 2}, {"id": "f4", "answer": "Yes. We provide treatment for post-accident pain and aftereffects covered by auto insurance, and assist with insurance claims.", "category": "Insurance", "question": "Do you accept auto insurance?", "sortOrder": 3}], "about": {"facilityImages": ["https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025106891-816o6q.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025115296-al2935.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787024974124-e0ob1i.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787024990001-2py25g.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787024998457-aep3y9.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025016656-q69vq6.webp", "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787025029104-yb6yiq.webp"], "philosophyBody": "Our clinic pursues treatment that goes beyond merely alleviating symptoms — we deeply understand each patient''s constitution and lifestyle to address root causes. Combining the wisdom of traditional Korean medicine with modern medical precision, we prescribe recovery for your daily life.", "philosophyTitle": "Our Philosophy"}, "menus": [{"id": "m1", "href": "/", "label": "Home", "isHidden": false, "sortOrder": 0, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779287749874-snvdoz.webp"}, {"id": "m2", "href": "/events", "label": "Events", "isHidden": false, "sortOrder": 1, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289822668-x74srd.webp"}, {"id": "m3", "href": "/treatments", "label": "Treatments", "isHidden": false, "sortOrder": 2, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289741816-8ntzs0.webp"}, {"id": "m4", "href": "/about", "label": "About", "isHidden": false, "sortOrder": 3, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289727340-4afelh.webp"}, {"id": "m5", "href": "/community/notice", "label": "Community", "isHidden": false, "sortOrder": 4, "bannerImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1779289767125-ghnel8.webp"}], "popup": {"id": "p1", "body": "A personalized diet program based on constitutional analysis. Special 30% discount throughout May.", "image": "", "title": "May Diet Package\\n30% Off", "linkUrl": "/events", "isActive": true}, "stats": [{"label": "Years of Practice", "value": 15, "suffix": "yr"}, {"label": "Patients Served", "value": 30000, "suffix": "+"}, {"label": "Satisfaction Rate", "value": 98, "suffix": "%"}, {"label": "Specialties", "value": 5, "suffix": ""}], "events": [{"id": 8, "date": "EVENT · 2026.05", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1787026443974-lnomjk.webp", "title": "볼링크 / 볼뉴머 / 슈링크", "endDate": "", "subtitle": "오픈특가", "st