orage/v1/object/public/site-assets/images/1786431991229-ty7sw0.webp\\"><p></p>"}], "notices": [{"id": 1, "date": "2026.05.14", "type": "event", "title": "May Diet Package - 30% Off Promotion", "content": "We are offering a personalized diet program based on constitutional analysis at a 30% discount throughout May.\\n\\nTarget: Anyone looking to manage their weight\\nPeriod: May 1 – May 31, 2026\\n\\nPlease book via phone or Naver Reservation.", "endDate": "2026-05-31", "startDate": "2026-05-01"}, {"id": 2, "date": "2026.05.10", "type": "notice", "title": "Closed on Buddha''s Birthday (May 25)", "content": "We will be closed on May 25 (Monday) for Buddha''s Birthday.\\n\\nRegular hours resume on May 26 (Tuesday).\\nWe apologize for any inconvenience.", "endDate": "2026-05-25", "startDate": "2026-05-10"}, {"id": 3, "date": "2026.05.02", "type": "notice", "title": "Schedule Change - Saturday Afternoon Hours Added", "content": "Based on patient requests, we are extending Saturday hours.\\n\\nBefore: Saturday 09:00 – 13:00\\nAfter: Saturday 09:00 – 16:00\\n\\nEffective: May 3, 2026 (Saturday)\\nLunch break (13:00–14:00) remains the same.", "startDate": "2026-05-02"}, {"id": 4, "date": "2026.04.20", "type": "notice", "title": "New Associate Director Joining Announcement", "content": "Hello, this is Gowoonbit Korean Medicine Clinic.\\n\\nA new associate director has joined our team starting April 21, 2026.\\nWe will continue to provide specialized and attentive care.\\n\\nThank you.", "startDate": "2026-04-20"}], "director": {"bio": ["Graduated from Kyung Hee University, College of Korean Medicine", "M.S. & Ph.D. in Korean Medicine, Kyung Hee University", "Sports Korean Medicine Team Doctor Certification", "Certified Member, Spinal Nerve Chuna Medicine Society", "Member, Korean Society of Oriental Internal Medicine"], "name": "Eunju Heo", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/ko-1779287679673-s4ysvn.jpg", "quote": "I pursue treatment that cares for both\\nbody and mind, helping fundamental recovery.", "title": "Director", "nameEn": "HEO EUNJU"}, "showStats": false, "clinicInfo": {"name": "Gowoonbit Korean Medicine Clinic", "hours": {"closed": "Sun & Holidays Closed", "weekday": "Weekdays 09:00 – 19:00", "saturday": "Saturday 09:00 – 14:00"}, "phone": "02-XXX-XXXX", "address": "123, OO-daero, OO-gu, Seoul, South Korea", "socialLinks": {"blog": "#", "kakao": "#", "instagram": "#"}, "bannerImages": {"about": "", "events": "", "community": "", "treatments": ""}, "defaultImage": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783758914500-yaanod.webp", "reservationUrl": "https://m.place.naver.com/place/2015359820/booking?entry=plt"}, "heroSlides": [{"id": 1, "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1780623209148-ho326v.webp", "label": "Korean Medicine Clinic", "title": "A Prescription of\\nComfort and Recovery", "subtitle": "So today''s pain doesn''t become tomorrow''s obstacle\\nWe restore the vibrant daily life you''ve been missing"}, {"id": 2, "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1780623296262-mazqvz.webp", "label": "Tradition meets Modern", "title": "A Place of Rest for\\nBody and Mind", "subtitle": "Combining the wisdom of traditional Korean medicine\\nwith modern precision for your healthy life"}, {"id": 3, "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1780623343534-hxg2sf.webp", "label": "Care from the Root", "title": "Treating Health\\nat Its Roots", "subtitle": "We carefully examine your constitution and lifestyle\\nto support fundamental recovery"}], "treatments": [{"id": 1, "slug": "pain", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783511098146-wvihnm.webp", "title": "Pain Treatment", "number": "01", "description": "Korean medicine treatment for chronic pain in the back, neck, and joints"}, {"id": 2, "slug": "insurance", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783510400343-b1zyp6.webp", "title": "Auto Insurance\\nTreatment", "number": "02", "description": "Post-accident pain and aftereffect treatment covered by auto insurance"}, {"id": 3, "slug": "diet", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783510978207-2ba1gw.webp", "title": "Diet\\nProgram", "number": "03", "description": "Healthy weight loss through personalized prescriptions based on body constitution"}, {"id": 4, "slug": "beauty", "image": "https://wtxxhfndfupgipidayqk.supabase.co/storage/v1/object/public/site-assets/images/1783510262621-klqgda.webp", "title": "Cosmetic\\nTreatment", "number": "04", "description": "Natural facial contouring and skin care through Korean medicine aesthetics"}, {"id": 5, "slug": "tonic", "image": "", "title": "Herbal Tonic", "number": "05", "description": "Customized herbal tonics for energy recovery and immune system support"}], "schedulePopup": {"id": "sp1", "rows": [{"day": "Weekdays", "hours": "09:00 – 19:00"}, {"day": "Saturday", "hours": "09:00 – 14:00"}, {"day": "Sun & Holidays", "hours": "Closed"}, {"day": "Jun 6 (Memorial Day)", "note": "Holiday", "hours": "Closed"}], "month": "2026.06", "title": "June Schedule", "notice": "Lunch break 13:00 – 14:00", "isActive": true}}'::jsonb) on conflict (locale) do update set data = excluded.data;
